import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.dMg474VA.js";const h=JSON.parse('{"title":"RLGW LLM Safety & Prompt Hardening Guide","description":"","frontmatter":{},"headers":[],"relativePath":"llm-safety.md","filePath":"llm-safety.md"}'),i={name:"llm-safety.md"};function o(d,e,s,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="rlgw-llm-safety-prompt-hardening-guide" tabindex="-1">RLGW LLM Safety &amp; Prompt Hardening Guide <a class="header-anchor" href="#rlgw-llm-safety-prompt-hardening-guide" aria-label="Permalink to &quot;RLGW LLM Safety &amp; Prompt Hardening Guide&quot;">​</a></h1><p>This document defines the safeguards protecting the Tier B forensic prompt engine and incident context builder from prompt injection, data poisoning, and credential leakage.</p><hr><h2 id="_1-redaction-canary-protection" tabindex="-1">1. Redaction &amp; Canary Protection <a class="header-anchor" href="#_1-redaction-canary-protection" aria-label="Permalink to &quot;1. Redaction &amp; Canary Protection&quot;">​</a></h2><ol><li><strong>Pre-Context Scrubbing</strong>: All incident data assembled by <code>DiagnosticContextBuilder</code> passes through <code>SensitiveRedactor</code>. Authorization headers, Bearer tokens, cookies, API keys (<code>rlk_*</code>), and JWTs are replaced with <code>[REDACTED]</code>.</li><li><strong>Canary Secret Verification</strong>: Automated regression tests inject unique canary strings (<code>canary_secret_xyz</code>) into all telemetry pathways and assert that zero canaries ever appear in the generated prompt context.</li></ol><hr><h2 id="_2-prompt-injection-hardening" tabindex="-1">2. Prompt Injection Hardening <a class="header-anchor" href="#_2-prompt-injection-hardening" aria-label="Permalink to &quot;2. Prompt Injection Hardening&quot;">​</a></h2><ol><li><strong>Strict Data Delimitation</strong>: User-derived telemetry and logs are encapsulated inside <code>&lt;incident_data&gt;&lt;![CDATA[ ... ]]&gt;&lt;/incident_data&gt;</code> blocks. Any raw XML tags inside payloads are sanitized to prevent tag breakout.</li><li><strong>System Instruction Precedence</strong>: System prompts instruct the LLM that content inside <code>&lt;incident_data&gt;</code> is untrusted data that must never be executed as instructions.</li><li><strong>Structured Schema Validation</strong>: All model outputs are strictly parsed and validated against the Zod <code>ForensicReportSchema</code>. Any extraneous fields or conversational preamble are stripped. If the model fails or behaves adversarially, the system safely falls back to a deterministic heuristic template.</li></ol>',8)])])}const g=t(i,[["render",o]]);export{h as __pageData,g as default};
